import React, { useState } from 'react';
import ArtistManagerNav from '../ArtistManagerNav/ArtistManagerNav';
import { useNavigate } from 'react-router-dom';

function Artist() {
  const navigate = useNavigate();
  const [inputs, setInputs] = useState({
    artistName: "",
    genre: "",
    category: "",
    bookingPrice: "",
    summary: "",
    bio: "",
    image: null,  // Will store the selected file object
  });

  // Local state only for image preview URL (not sent to backend)
  const [preview, setPreview] = useState("");

  const handleChange = (e) => {
    setInputs((prevState) => ({
      ...prevState,
      [e.target.name]:e.target.value,
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setInputs(prev => ({ ...prev, image: file }));
      setPreview(URL.createObjectURL(file));  // Preview locally only
    }
  };

  return (
    <div>
      <ArtistManagerNav />
      <h1>Add New Artist</h1>

      <form style={{ maxWidth: "500px" }}>
        <label>
          Artist Name:
          <input type="text" name="artistName" value={inputs.artistName} onChange={handleChange}/>
        </label>

        <br /><br />

        <label>
          Genre:
          <input
            type="text"
            name="genre"
            value={inputs.genre}
            onChange={handleChange}
          />
        </label>

        <br /><br />

        <label>
          Category:
          <input
            type="text"
            name="category"
            value={inputs.category}
            onChange={handleChange}
          />
        </label>

        <br /><br />

        <label>
          Booking Price:
          <input
            type="number"
            name="bookingPrice"
            min="0"
            step="0.01"
            value={inputs.bookingPrice}
            onChange={handleChange}
          />
        </label>

        <br /><br />

        <label>
          Summary:
          <textarea
            name="summary"
            rows="3"
            value={inputs.summary}
            onChange={handleChange}
          />
        </label>

        <br /><br />

        <label>
          Bio:
          <textarea
            name="bio"
            rows="5"
            value={inputs.bio}
            onChange={handleChange}
          />
        </label>

        <br /><br />

        <label>
          Choose Image:
          <input
            type="file"
            accept="image/*"
            onChange={handleImageChange}
          />
        </label>

        <br />
        {preview && (
          <img
            src={preview}
            alt="Preview"
            style={{ width: "150px", height: "150px", objectFit: "cover", marginTop: "10px" }}
          />
        )}

        <br /><br />

        <button type="submit">Add Artist</button>
      </form>
    </div>
  );
}

export default Artist;
